export { default as DistortionWave } from './DistortionWave.vue';
export type {
  DistortionWaveBox,
  DistortionWaveExpose,
  DistortionWaveMotion,
  DistortionWavePlayOptions,
  DistortionWavePoint,
  DistortionWaveProps,
  DistortionWaveSource,
  DistortionWaveTheme,
} from './types';

/* Draws a live element into a canvas: the element is cloned with every
   computed style written inline, wrapped in an SVG <foreignObject> and
   drawn as an image. Same-origin web fonts are embedded so the text in the
   picture matches the page. */

const XHTML = 'http://www.w3.org/1999/xhtml';
const SVG = 'http://www.w3.org/2000/svg';
const SKIP = '[data-wave-skip]';

let fontsCss: Promise<string> | null = null;

function toDataUrl(url: string): Promise<string> {
  return fetch(url)
    .then((r) => (r.ok ? r.blob() : Promise.reject(new Error(url))))
    .then(
      (blob) =>
        new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () =>
            typeof reader.result === 'string'
              ? resolve(reader.result)
              : reject(new Error('read'));
          reader.onerror = () => reject(new Error('read'));
          reader.readAsDataURL(blob);
        }),
    );
}

function fontFaces(): CSSFontFaceRule[] {
  const out: CSSFontFaceRule[] = [];
  const walk = (rules: CSSRuleList) => {
    for (const rule of Array.from(rules)) {
      if (rule instanceof CSSFontFaceRule) out.push(rule);
      else if (rule instanceof CSSGroupingRule) walk(rule.cssRules);
      else if (rule instanceof CSSImportRule && rule.styleSheet)
        walk(rule.styleSheet.cssRules);
    }
  };
  for (const sheet of Array.from(document.styleSheets)) {
    try {
      walk(sheet.cssRules);
    } catch {
      // A sheet from another origin: its fonts stay out.
    }
  }
  return out;
}

async function embedFace(rule: CSSFontFaceRule): Promise<string> {
  const base = rule.parentStyleSheet?.href ?? document.baseURI;
  let css = rule.cssText;
  const urls = Array.from(css.matchAll(/url\((["']?)([^"')]+)\1\)/g));
  for (const match of urls) {
    const raw = match[2] ?? '';
    if (raw.startsWith('data:')) continue;
    const abs = new URL(raw, base);
    if (abs.origin !== location.origin) return '';
    css = css.replace(match[0], `url("${await toDataUrl(abs.href)}")`);
  }
  return css;
}

/** The page's same-origin @font-face rules with the fonts inlined, once. */
function pageFonts(): Promise<string> {
  fontsCss ??= Promise.all(
    fontFaces().map((rule) => embedFace(rule).catch(() => '')),
  ).then((list) => list.join(''));
  return fontsCss;
}

function inline(from: Element, to: Element) {
  if (!(to instanceof HTMLElement || to instanceof SVGElement)) return;
  if (from.matches(SKIP)) return;
  const cs = getComputedStyle(from);
  let text = '';
  for (let i = 0; i < cs.length; i++) {
    const name = cs.item(i);
    text += `${name}:${cs.getPropertyValue(name)};`;
  }
  to.setAttribute('style', text);
  to.removeAttribute('class');
  if (from instanceof HTMLCanvasElement && to instanceof HTMLCanvasElement) {
    const img = document.createElementNS(XHTML, 'img');
    try {
      img.setAttribute('src', from.toDataURL());
    } catch {
      // A tainted canvas draws as an empty box.
    }
    img.setAttribute('style', text);
    to.replaceWith(img);
    return;
  }
  const icon = maskedIcon(cs);
  if (icon && from.children.length === 0) {
    const img = document.createElementNS(XHTML, 'img');
    img.setAttribute('src', icon);
    img.setAttribute(
      'style',
      `${text}mask:none;-webkit-mask:none;background:none;`,
    );
    to.replaceWith(img);
    return;
  }
  const kids = Array.from(from.children);
  const copies = Array.from(to.children);
  kids.forEach((kid, i) => {
    const copy = copies[i];
    if (copy) inline(kid, copy);
  });
}

/** The first solid background colour at or above `el`. */
export function backdrop(el: Element): string {
  for (let node: Element | null = el; node; node = node.parentElement) {
    const c = getComputedStyle(node).backgroundColor;
    if (c && c !== 'transparent' && !/,\s*0\)$|\/\s*0\)$/.test(c)) return c;
  }
  return 'rgb(255, 255, 255)';
}

/* A CSS-mask icon (an SVG data URL painted with the background colour)
   does not draw inside the picture, so it becomes an image of the SVG
   painted in that colour. */
function maskedIcon(cs: CSSStyleDeclaration): string | null {
  const mask =
    cs.getPropertyValue('mask-image') ||
    cs.getPropertyValue('-webkit-mask-image');
  const m = /^url\("data:image\/svg\+xml,(.+)"\)$/.exec(mask);
  if (!m?.[1]) return null;
  let svg: string;
  try {
    svg = decodeURIComponent(m[1]);
  } catch {
    return null;
  }
  // Only the mask's alpha counted: paint every stroke and fill in the colour.
  const paint = cs.backgroundColor;
  svg = svg.replace(
    /\b(stroke|fill)=(['"])(?!none\2)[^'"]*\2/g,
    (_all, attr: string, q: string) => `${attr}=${q}${paint}${q}`,
  );
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

export interface RasterOptions {
  /** The layer to show; the other layers are left out. */
  layer: HTMLElement;
  scale: number;
}

/** A picture of `root` with only `layer` showing, at `scale` × CSS px. */
export async function rasterize(
  root: HTMLElement,
  { layer, scale }: RasterOptions,
): Promise<HTMLCanvasElement> {
  const width = root.offsetWidth;
  const height = root.offsetHeight;
  const clone = root.cloneNode(true);
  if (!(clone instanceof HTMLElement)) throw new Error('clone');
  inline(root, clone);
  // Leave out the overlay, the canvas and every other layer.
  const index = Array.from(root.children).indexOf(layer);
  Array.from(clone.children).forEach((child, i) => {
    if (i === index) {
      child.setAttribute(
        'style',
        `${child.getAttribute('style') ?? ''}opacity:1;visibility:visible;`,
      );
    } else if (child.matches('[data-wave-layer]')) child.remove();
  });
  for (const node of Array.from(clone.querySelectorAll(SKIP))) node.remove();
  clone.setAttribute(
    'style',
    `${clone.getAttribute('style') ?? ''}position:relative;left:0;top:0;margin:0;transform:none;translate:none;scale:none;rotate:none;opacity:1;width:${width}px;height:${height}px;box-sizing:border-box;border-radius:0;`,
  );
  const fonts = await pageFonts();
  const W = Math.max(1, Math.round(width * scale));
  const H = Math.max(1, Math.round(height * scale));
  // Scale with a CSS transform, not the SVG viewBox: Safari draws
  // <foreignObject> content at 1:1 and ignores viewBox scaling, which
  // shrank the picture to 1/devicePixelRatio of the card on iPhones.
  const wrap = document.createElementNS(XHTML, 'div');
  wrap.setAttribute(
    'style',
    `width:${width}px;height:${height}px;transform:scale(${W / width},${H / height});transform-origin:0 0;`,
  );
  const style = document.createElementNS(XHTML, 'style');
  style.textContent = fonts;
  wrap.append(style, clone);
  const xml = new XMLSerializer().serializeToString(wrap);
  const svg = `<svg xmlns="${SVG}" width="${W}" height="${H}"><foreignObject x="0" y="0" width="${W}" height="${H}">${xml}</foreignObject></svg>`;
  const img = new Image();
  img.decoding = 'async';
  img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  await img.decode();
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2d');
  ctx.fillStyle = backdrop(root);
  ctx.fillRect(0, 0, W, H);
  ctx.drawImage(img, 0, 0, W, H);
  return canvas;
}

import type { ComponentPublicInstance, HTMLAttributes } from 'vue';

/** A built-in colour set for the wave's glowing edge. */
export type DistortionWaveTheme = 'prism' | 'meadow' | 'lagoon' | 'ember';

/** Where the wave leaves from: an element (or a component), a box in the
 *  wave's own CSS pixels, or nothing to use the last pressed control. */
export type DistortionWaveSource =
  | Element
  | ComponentPublicInstance
  | DistortionWaveBox
  | null
  | undefined;

export interface DistortionWaveBox {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface DistortionWavePoint {
  x: number;
  y: number;
}

export type DistortionWaveMotion = 'auto' | 'full' | 'reduce';

export interface DistortionWaveProps {
  /** Which view shows. Changing it runs the wave (use `v-model:revealed`). */
  revealed?: boolean;
  /** The element, component or box the wave leaves from. */
  source?: DistortionWaveSource;
  /** A preset, or 2–4 colours (`#rrggbb`) for the glowing edge. */
  colors?: DistortionWaveTheme | string[];
  /** Seconds the wave takes to cross. */
  duration?: number;
  /** Seconds the wave takes to fold back. */
  returnDuration?: number;
  /** How strongly the edge bends what it passes over (0–2). */
  refraction?: number;
  /** How far the colour channels split at the edge (0–2). */
  aberration?: number;
  /** How far the front leans toward the press (0–1). */
  lean?: number;
  /** Sparks behind the front. */
  sparks?: boolean;
  /** Corner radius of the glow in CSS pixels. Default: the element's own. */
  radius?: number;
  /** `auto` follows the reduced-motion setting; `reduce` always crossfades. */
  motion?: DistortionWaveMotion;
  class?: HTMLAttributes['class'];
}

export interface DistortionWavePlayOptions {
  source?: DistortionWaveSource;
  /** The press point in the wave's CSS pixels: the front leans toward it. */
  point?: DistortionWavePoint | null;
}

export interface DistortionWaveExpose {
  /** Runs the wave to the revealed view. */
  play: (options?: DistortionWavePlayOptions) => void;
  /** Folds the wave back to the first view. */
  reverse: () => void;
  /** Jumps to the first view with no wave. */
  reset: () => void;
  /** Takes the pictures now so the next wave starts at once. */
  prepare: () => Promise<void>;
}

/** Everything the shader needs for one frame. */
export interface WaveFrame {
  /** Source centre, CSS px. */
  cx: number;
  cy: number;
  /** How much wider than tall the front grows (1 = a ring). */
  hw: number;
  /** The source's own radius, CSS px. */
  hh: number;
  /** Lean direction times strength. */
  lx: number;
  ly: number;
  /** Front distance from the source, CSS px. */
  reach: number;
  /** Width of the bending band, CSS px. */
  band: number;
  /** Pull toward the source before launch, 0–1. */
  pull: number;
  /** Strength of the glowing band, 0–1. */
  glow: number;
  /** Strength of the glow left on the rim, 0–1. */
  rim: number;
  /** How far the revealed view has cleared its blur, 0–1. */
  settle: number;
  time: number;
}

export interface WaveLook {
  colors: [number, number, number][];
  refraction: number;
  aberration: number;
  sparks: boolean;
  radius: number;
  light: boolean;
}

import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
import {
  useEventListener,
  useMutationObserver,
  usePreferredReducedMotion,
  useResizeObserver,
} from '@vueuse/core';
import { backdrop, rasterize } from './raster';
import { createWaveRenderer } from './wave-renderer';
import { THEMES, frameAt, toRgb } from './wave-timeline';
import type { Ref } from 'vue';
import type { WaveRenderer } from './wave-renderer';
import type {
  DistortionWaveBox,
  DistortionWavePlayOptions,
  DistortionWavePoint,
  DistortionWaveProps,
  DistortionWaveSource,
  WaveFrame,
} from './types';

const INTERACTIVE = 'button, a[href], [role=button], input, [data-wave-source]';
const FADE_MS = 300;

interface Elements {
  root: Ref<HTMLElement | null>;
  first: Ref<HTMLElement | null>;
  next: Ref<HTMLElement | null>;
  canvas: Ref<HTMLCanvasElement | null>;
}

interface Picture {
  canvas: HTMLCanvasElement | null;
  dirty: boolean;
}

function isBox(v: object): v is DistortionWaveBox {
  return 'x' in v && 'y' in v && 'width' in v && 'height' in v;
}

function elementOf(source: DistortionWaveSource): Element | null {
  if (!source) return null;
  if (source instanceof Element) return source;
  if ('$el' in source && source.$el instanceof Element) return source.$el;
  return null;
}

function luminance(color: string): number {
  const m = color.match(/[\d.]+/g);
  if (!m || m.length < 3) return 0;
  const [r, g, b] = m.map(Number);
  return (0.299 * (r ?? 0) + 0.587 * (g ?? 0) + 0.114 * (b ?? 0)) / 255;
}

export function useWaveEngine(
  props: Readonly<DistortionWaveProps>,
  els: Elements,
  onDone: (revealed: boolean) => void,
) {
  /** The live view showing: 0 the first, 1 the revealed one. */
  const shown = ref<0 | 1>(props.revealed ? 1 : 0);
  /** The layers crossfade (reduced motion or no WebGL 2). */
  const fading = ref(false);
  const reduced = usePreferredReducedMotion();
  const pictures: Picture[] = [
    { canvas: null, dirty: true },
    { canvas: null, dirty: true },
  ];
  const frame: WaveFrame = {
    cx: 0,
    cy: 0,
    hw: 1,
    hh: 1,
    lx: 0,
    ly: 0,
    reach: 0,
    band: 1,
    pull: 0,
    glow: 0,
    rim: 0,
    settle: 0,
    time: 0,
  };
  let renderer: WaveRenderer | null = null;
  let failed = false;
  let raf = 0;
  let fadeTimer: ReturnType<typeof setTimeout> | undefined;
  let token = 0;
  let u: number = shown.value;
  let target: 0 | 1 = shown.value;
  let distance = 1;
  let band = 1;
  let started = 0;
  let last = 0;
  let press: { el: Element | null; x: number; y: number; t: number } | null =
    null;

  const crossfade = () =>
    props.motion === 'reduce' ||
    (props.motion !== 'full' && reduced.value === 'reduce');

  function ensureRenderer(): WaveRenderer | null {
    if (renderer || failed || !els.canvas.value) return renderer;
    renderer = createWaveRenderer(els.canvas.value);
    failed = !renderer;
    return renderer;
  }

  function local(r: DOMRect): DistortionWaveBox {
    const box = els.root.value?.getBoundingClientRect();
    return {
      x: r.left - (box?.left ?? 0),
      y: r.top - (box?.top ?? 0),
      width: r.width,
      height: r.height,
    };
  }

  function aim(options?: DistortionWavePlayOptions) {
    const root = els.root.value;
    if (!root) return;
    const w = root.offsetWidth;
    const h = root.offsetHeight;
    const recent = press && performance.now() - press.t < 2000 ? press : null;
    const given = options?.source ?? props.source;
    let box: DistortionWaveBox | null =
      given && !(given instanceof Element) && isBox(given) ? given : null;
    const el = elementOf(given) ?? (box ? null : (recent?.el ?? null));
    if (el) {
      const r = el.getBoundingClientRect();
      if (r.width > 0 && r.height > 0) box = local(r);
    }
    box ??= { x: w * 0.2, y: h - 64, width: w * 0.6, height: 44 };
    const cx = box.x + box.width / 2;
    const cy = box.y + box.height / 2;
    const point: DistortionWavePoint | null =
      options?.point ??
      (recent ? local(new DOMRect(recent.x, recent.y, 0, 0)) : null);
    let lx = 0;
    let ly = 0;
    if (point) {
      const dx = point.x - cx;
      const dy = point.y - cy;
      const len = Math.hypot(dx, dy);
      const k = Math.min(1, len / Math.max(box.width / 2, 1));
      if (len > 0.5) {
        lx = (dx / len) * k * (props.lean ?? 0.2);
        ly = (dy / len) * k * (props.lean ?? 0.2);
      }
    }
    // A wide source widens the front into a dome; a round one makes a ring.
    const widen = Math.min(
      Math.max(Math.sqrt(box.width / Math.max(box.height, 1)) * 0.44, 1),
      1.35,
    );
    const own = Math.min(box.width, box.height) / 2;
    Object.assign(frame, { cx, cy, hw: widen, hh: own, lx, ly });
    const corners = [
      [0, 0],
      [w, 0],
      [0, h],
      [w, h],
    ];
    const far = Math.max(
      ...corners.map(([x = 0, y = 0]) =>
        Math.max(Math.hypot((x - cx) / widen, y - cy) - own, 0),
      ),
    );
    band = Math.min(Math.max(Math.max(w, h) * 0.28, 40), 190);
    distance = far * 1.08 + band * 2.6;
  }

  async function capture(which: 0 | 1) {
    const pic = pictures[which];
    const root = els.root.value;
    const layer =
      which === 0 ? els.first.value : (els.next.value ?? els.first.value);
    if (!pic || !root || !layer) return;
    if (pic.canvas && !pic.dirty) return;
    pic.dirty = false;
    try {
      pic.canvas = await rasterize(root, {
        layer,
        scale: Math.min(globalThis.devicePixelRatio || 1, 2),
      });
    } catch {
      pic.canvas = null;
    }
  }

  function look() {
    const root = els.root.value;
    const radius =
      props.radius ??
      Number.parseFloat(
        root ? getComputedStyle(root).borderTopLeftRadius : '0',
      );
    const colors = props.colors ?? 'prism';
    return {
      colors: toRgb(typeof colors === 'string' ? THEMES[colors] : colors),
      refraction: props.refraction ?? 1,
      aberration: props.aberration ?? 1,
      sparks: props.sparks ?? true,
      radius: Number.isFinite(radius) ? radius : 0,
      light: root ? luminance(backdrop(root)) > 0.55 : false,
    };
  }

  function placeCanvas() {
    const root = els.root.value;
    const canvas = els.canvas.value;
    if (!root || !canvas) return;
    const cs = getComputedStyle(root);
    const scale = Math.min(globalThis.devicePixelRatio || 1, 2);
    canvas.style.left = `${-Number.parseFloat(cs.borderLeftWidth) || 0}px`;
    canvas.style.top = `${-Number.parseFloat(cs.borderTopWidth) || 0}px`;
    canvas.style.width = `${root.offsetWidth}px`;
    canvas.style.height = `${root.offsetHeight}px`;
    canvas.width = Math.round(root.offsetWidth * scale);
    canvas.height = Math.round(root.offsetHeight * scale);
  }

  function paint(r: WaveRenderer, now: number) {
    const root = els.root.value;
    if (!root) return;
    frameAt({ u, time: (now - started) / 1000, distance, band }, frame);
    r.draw(frame, look(), root.offsetWidth, root.offsetHeight);
  }

  function finish(to: 0 | 1) {
    cancelAnimationFrame(raf);
    raf = 0;
    shown.value = to;
    void nextTick(() => {
      if (els.canvas.value) els.canvas.value.style.display = 'none';
    });
    onDone(to === 1);
  }

  function tick(now: number) {
    const r = renderer;
    if (!r) return;
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;
    const dur =
      target === 1 ? (props.duration ?? 1.6) : (props.returnDuration ?? 0.9);
    u = Math.min(
      Math.max(u + (target === 1 ? dt : -dt) / Math.max(dur, 0.05), 0),
      1,
    );
    if (u === target) {
      finish(target);
      return;
    }
    paint(r, now);
    raf = requestAnimationFrame(tick);
  }

  function fade(to: 0 | 1) {
    clearTimeout(fadeTimer);
    fading.value = true;
    shown.value = to;
    u = to;
    fadeTimer = setTimeout(() => {
      fading.value = false;
      onDone(to === 1);
    }, FADE_MS);
  }

  async function go(to: 0 | 1, options?: DistortionWavePlayOptions) {
    target = to;
    if (raf) return;
    if (u === to && !options) return;
    const r = crossfade() ? null : ensureRenderer();
    if (!r) {
      fade(to);
      return;
    }
    const mine = ++token;
    const resting = u === 0 || u === 1;
    if (resting) aim(options);
    await Promise.all([capture(0), capture(1)]);
    const [a, b] = pictures;
    if (mine !== token || !a?.canvas || !b?.canvas) {
      if (mine === token) fade(to);
      return;
    }
    placeCanvas();
    r.setViews(a.canvas, b.canvas);
    started = last = performance.now();
    if (els.canvas.value) {
      paint(r, started);
      els.canvas.value.style.display = 'block';
    }
    raf = requestAnimationFrame(tick);
  }

  function markDirty() {
    for (const p of pictures) p.dirty = true;
  }

  function prewarm() {
    if (crossfade() || !ensureRenderer()) return;
    void capture(0).then(() => capture(1));
  }

  function reset() {
    token++;
    cancelAnimationFrame(raf);
    raf = 0;
    clearTimeout(fadeTimer);
    fading.value = false;
    u = target = 0;
    shown.value = 0;
    if (els.canvas.value) els.canvas.value.style.display = 'none';
  }

  useEventListener(
    els.root,
    'pointerdown',
    (e: PointerEvent) => {
      const t = e.target;
      const el = t instanceof Element ? t.closest(INTERACTIVE) : null;
      press = { el, x: e.clientX, y: e.clientY, t: performance.now() };
    },
    { capture: true, passive: true },
  );
  useMutationObserver(
    els.root,
    (records) => {
      const real = records.some((rec) => {
        const n = rec.target;
        const el = n instanceof Element ? n : n.parentElement;
        if (el?.closest('[data-wave-skip]')) return false;
        return !(
          rec.type === 'attributes' && el?.hasAttribute('data-wave-layer')
        );
      });
      if (real) markDirty();
    },
    { subtree: true, childList: true, attributes: true, characterData: true },
  );
  useResizeObserver(els.root, markDirty);
  // Theme switches and late stylesheets (icons, fonts) change the pictures too.
  const html = ref<HTMLElement | null>(null);
  const head = ref<HTMLElement | null>(null);
  onMounted(() => {
    html.value = document.documentElement;
    head.value = document.head;
  });
  useMutationObserver(html, markDirty, {
    attributes: true,
    attributeFilter: ['class', 'style', 'data-theme'],
  });
  useMutationObserver(head, markDirty, {
    childList: true,
    subtree: true,
    characterData: true,
  });

  onBeforeUnmount(() => {
    token++;
    cancelAnimationFrame(raf);
    clearTimeout(fadeTimer);
    renderer?.dispose();
    renderer = null;
  });

  return {
    shown,
    fading,
    go,
    reset,
    prewarm,
    play: (options?: DistortionWavePlayOptions) => {
      if (!raf) {
        reset();
        u = 0;
      }
      void go(1, options ?? {});
    },
    prepare: async () => {
      if (crossfade() || !ensureRenderer()) return;
      await Promise.all([capture(0), capture(1)]);
    },
  };
}

import { FRAGMENT, VERTEX } from './wave-shader';
import type { WaveFrame, WaveLook } from './types';

const UNIFORMS = [
  'uFirst',
  'uNext',
  'uSize',
  'uScale',
  'uSource',
  'uLean',
  'uReach',
  'uBand',
  'uPull',
  'uGlow',
  'uRim',
  'uSettle',
  'uTime',
  'uRefract',
  'uSplit',
  'uSparks',
  'uRadius',
  'uLight',
  'uColors',
] as const;

type Uniform = (typeof UNIFORMS)[number];

function shader(gl: WebGL2RenderingContext, type: number, source: string) {
  const s = gl.createShader(type);
  if (!s) throw new Error('shader');
  gl.shaderSource(s, source);
  gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS))
    throw new Error(gl.getShaderInfoLog(s) ?? 'compile');
  return s;
}

export interface WaveRenderer {
  /** Uploads the two views; either may be the same picture. */
  setViews: (first: TexImageSource, next: TexImageSource) => void;
  draw: (
    frame: WaveFrame,
    look: WaveLook,
    width: number,
    height: number,
  ) => void;
  dispose: () => void;
}

/** A WebGL 2 renderer on `canvas`, or null where WebGL 2 is missing. */
export function createWaveRenderer(
  canvas: HTMLCanvasElement,
): WaveRenderer | null {
  const gl = canvas.getContext('webgl2', {
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
  });
  if (!gl) return null;
  let program: WebGLProgram;
  try {
    const p = gl.createProgram();
    if (!p) return null;
    gl.attachShader(p, shader(gl, gl.VERTEX_SHADER, VERTEX));
    gl.attachShader(p, shader(gl, gl.FRAGMENT_SHADER, FRAGMENT));
    gl.bindAttribLocation(p, 0, 'aPos');
    gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) return null;
    program = p;
  } catch {
    return null;
  }
  const buffer = gl.createBuffer();
  const textures = [gl.createTexture(), gl.createTexture()];
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
    gl.STATIC_DRAW,
  );
  const loc = new Map<Uniform, WebGLUniformLocation | null>();
  for (const name of UNIFORMS)
    loc.set(name, gl.getUniformLocation(program, name));
  const at = (name: Uniform) => loc.get(name) ?? null;
  const colors = new Float32Array(12);

  const upload = (tex: WebGLTexture | null, source: TexImageSource) => {
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);
    gl.generateMipmap(gl.TEXTURE_2D);
    gl.texParameteri(
      gl.TEXTURE_2D,
      gl.TEXTURE_MIN_FILTER,
      gl.LINEAR_MIPMAP_LINEAR,
    );
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  };

  return {
    setViews(first, next) {
      upload(textures[0] ?? null, first);
      upload(textures[1] ?? null, next);
    },
    draw(f, look, width, height) {
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.useProgram(program);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, textures[0] ?? null);
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_2D, textures[1] ?? null);
      gl.uniform1i(at('uFirst'), 0);
      gl.uniform1i(at('uNext'), 1);
      gl.uniform2f(at('uSize'), width, height);
      gl.uniform1f(at('uScale'), canvas.width / width);
      gl.uniform4f(at('uSource'), f.cx, f.cy, f.hw, f.hh);
      gl.uniform2f(at('uLean'), f.lx, f.ly);
      gl.uniform1f(at('uReach'), f.reach);
      gl.uniform1f(at('uBand'), f.band);
      gl.uniform1f(at('uPull'), f.pull);
      gl.uniform1f(at('uGlow'), f.glow);
      gl.uniform1f(at('uRim'), f.rim);
      gl.uniform1f(at('uSettle'), f.settle);
      gl.uniform1f(at('uTime'), f.time);
      gl.uniform1f(at('uRefract'), look.refraction);
      gl.uniform1f(at('uSplit'), look.aberration);
      gl.uniform1f(at('uSparks'), look.sparks ? 1 : 0);
      gl.uniform1f(at('uRadius'), look.radius);
      gl.uniform1f(at('uLight'), look.light ? 1 : 0);
      look.colors.forEach((c, i) => colors.set(c, i * 3));
      gl.uniform3fv(at('uColors'), colors);
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    },
    dispose() {
      for (const t of textures) gl.deleteTexture(t);
      gl.deleteBuffer(buffer);
      gl.deleteProgram(program);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}

export const VERTEX = `#version 300 es
in vec2 aPos;
void main() { gl_Position = vec4(aPos, 0.0, 1.0); }`;

/* One pass. Coordinates are CSS pixels from the top left of the element.
   d is the distance from the source box (its rounded outline grown
   outward), x = (d - reach) / band is the position across the front:
   negative behind it (the revealed view), positive ahead (the first view). */
export const FRAGMENT = `#version 300 es
precision highp float;
uniform sampler2D uFirst;
uniform sampler2D uNext;
uniform vec2 uSize;
uniform float uScale;
uniform vec4 uSource;
uniform vec2 uLean;
uniform float uReach;
uniform float uBand;
uniform float uPull;
uniform float uGlow;
uniform float uRim;
uniform float uSettle;
uniform float uTime;
uniform float uRefract;
uniform float uSplit;
uniform float uSparks;
uniform float uRadius;
uniform float uLight;
uniform vec3 uColors[4];
out vec4 outColor;

float box(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

// Distance from the source, measured on a widened ellipse so a wide button
// sends a dome and a round icon sends a ring. uSource.z widens, .w is the
// source's own radius.
float field(vec2 p) {
  vec2 q = p - uSource.xy;
  float d = max(length(q / vec2(uSource.z, 1.0)) - uSource.w, 0.0);
  float l = max(length(q), 1.0);
  return d * (1.0 - dot(q / l, uLean));
}

vec3 palette(float t) {
  t = fract(t) * 4.0;
  float i = floor(t);
  float f = smoothstep(0.0, 1.0, t - i);
  vec3 a = uColors[int(mod(i, 4.0))];
  vec3 b = uColors[int(mod(i + 1.0, 4.0))];
  return mix(a, b, f);
}

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

vec3 sampleView(sampler2D tex, vec2 p, vec2 n, float lod, float split) {
  vec2 px = 1.0 / uSize;
  float s = exp2(lod) * 0.5;
  vec2 t = vec2(-n.y, n.x);
  vec3 c = vec3(0.0);
  for (int i = 0; i < 4; i++) {
    float a = float(i) * 1.5708 + 0.785;
    vec2 o = (cos(a) * n + sin(a) * t) * s;
    vec2 uv = (p + o) * px;
    c.r += textureLod(tex, uv + n * split * px, lod).r;
    c.g += textureLod(tex, uv, lod).g;
    c.b += textureLod(tex, uv - n * split * px, lod).b;
  }
  return c * 0.25;
}

void main() {
  vec2 p = vec2(gl_FragCoord.x, uSize.y * uScale - gl_FragCoord.y) / uScale;
  float edge = box(p - uSize * 0.5, uSize * 0.5, min(uRadius, min(uSize.x, uSize.y) * 0.5));
  float inside = clamp(0.5 - edge * uScale, 0.0, 1.0);
  if (inside <= 0.0) { outColor = vec4(0.0); return; }

  float d = field(p);
  vec2 e = vec2(1.0, 0.0);
  vec2 g = vec2(field(p + e.xy) - field(p - e.xy), field(p + e.yx) - field(p - e.yx));
  vec2 n = length(g) > 1e-4 ? normalize(g) : normalize(p - uSource.xy + 1e-3);
  float x = (d - uReach) / uBand;

  // Before launch the view is drawn toward the source.
  vec2 toSrc = uSource.xy - p;
  float near = exp(-length(toSrc) / (0.45 * max(uSize.x, uSize.y)));
  vec2 q = p + toSrc * uPull * 0.08 * near;

  // The lens: what lies under the front swells outward and bends.
  float lens = x * exp(-x * x * 1.6);
  q -= n * lens * uBand * 0.32 * uRefract * uGlow;
  float split = (uPull * near * 3.0 + exp(-x * x * 0.7) * 7.0 * uGlow) * uSplit;

  float ahead = max(x, 0.0);
  float behind = max(-x, 0.0);
  float lodA = (exp(-ahead * 1.4) * 3.2 * uGlow) + uPull * near * 0.8;
  float lodB = (exp(-behind * 0.9) * 3.6 + 1.6 * (1.0 - uSettle)) * (1.0 - uSettle * uSettle);

  vec3 first = sampleView(uFirst, q, n, lodA, split);
  vec3 next = sampleView(uNext, q, n, lodB, split * 0.8);
  float side = smoothstep(-0.35, 0.35, x);
  vec3 col = mix(next, first, side);

  // Haze just behind the front.
  float haze = exp(-pow((x + 0.9) / 0.9, 2.0)) * uGlow;
  col = mix(col, col * 0.5, haze * (1.0 - uLight * 0.8));

  float luma = dot(col, vec3(0.299, 0.587, 0.114));
  float hue = atan(n.y, n.x) / 6.2832 + uTime * 0.07;

  // The colourful band, its soft halo and a fine bright line at the front.
  float band = exp(-pow((x + 0.3) / 0.65, 2.0)) * 0.8 + exp(-x * x * 0.3) * 0.1;
  float line = exp(-pow(x / 0.04, 2.0)) * 0.2;
  vec3 tint = palette(hue + x * 0.22);
  float amount = band * uGlow;

  // The rim keeps colour where the front has passed, then fades.
  float passed = smoothstep(0.2, -1.2, x);
  float rimGlow = (exp(edge / 14.0) * 0.6 + exp(edge / 3.0) * 0.45) * passed * uRim;
  vec2 c = p - uSize * 0.5;
  vec3 rimTint = palette(atan(c.y, c.x) / 6.2832 + uTime * 0.05);

  // Sparks: fine dots scattered just behind the front.
  float sparks = 0.0;
  if (uSparks > 0.5) {
    vec2 cell = floor(p / 15.0);
    float h = hash(cell);
    vec2 at = (cell + 0.2 + 0.6 * vec2(h, hash(cell + 7.1))) * 15.0;
    float on = step(0.72, hash(cell + 3.7));
    float zone = smoothstep(-2.4, -1.4, x) * smoothstep(0.25, -0.1, x);
    float tw = 0.55 + 0.45 * sin(uTime * 9.0 + h * 40.0);
    sparks = on * zone * tw * smoothstep(1.3, 0.2, length(p - at)) * uGlow;
  }

  // On a dark view the colour is light added on top; on a light view it is
  // paint laid over, so it does not wash out to white.
  vec3 add = tint * amount + rimTint * rimGlow + vec3(line * uGlow) + vec3(sparks);
  vec3 onDark = col + add * (1.0 - luma * 0.7);
  vec3 onLight = mix(col, tint * 0.92, clamp(amount * 0.85, 0.0, 1.0));
  onLight = mix(onLight, rimTint * 0.95, clamp(rimGlow * 0.8, 0.0, 1.0));
  onLight = mix(onLight, tint * 0.7, clamp(line * uGlow * 1.5 + sparks, 0.0, 1.0));
  col = min(mix(onDark, onLight, uLight), vec3(1.0));
  outColor = vec4(col * inside, inside);
}`;

import type { DistortionWaveTheme, WaveFrame } from './types';

export const THEMES: Record<DistortionWaveTheme, string[]> = {
  prism: ['#ff4fb8', '#ff9a3d', '#4f8dff', '#a46bff'],
  meadow: ['#3ddc5a', '#a6f04a', '#1fbf6b', '#6dffb0'],
  lagoon: ['#3aa0ff', '#38e1d0', '#5b6bff', '#7fd4ff'],
  ember: ['#ff6a3d', '#ffc23d', '#ff3d6e', '#ff8f5a'],
};

const HEX = /^#?([\da-f]{6})$/i;

/** Hex colours to 0–1 RGB, always four of them (cycled). */
export function toRgb(list: string[]): [number, number, number][] {
  const parsed = list.flatMap((c): [number, number, number][] => {
    const m = HEX.exec(c.trim());
    if (!m?.[1]) return [];
    const v = Number.parseInt(m[1], 16);
    return [[((v >> 16) & 255) / 255, ((v >> 8) & 255) / 255, (v & 255) / 255]];
  });
  const base: [number, number, number][] = parsed.length ? parsed : [[1, 1, 1]];
  return [0, 1, 2, 3].map((i) => base[i % base.length] ?? [1, 1, 1]);
}

const clamp01 = (v: number) => Math.min(Math.max(v, 0), 1);
const smooth = (a: number, b: number, v: number) => {
  const t = clamp01((v - a) / (b - a));
  return t * t * (3 - 2 * t);
};

/** Where the front leaves its source, as a share of the run. */
const LAUNCH = 0.12;

export interface TimelineInput {
  /** Run progress 0–1. */
  u: number;
  /** Seconds since the run began. */
  time: number;
  /** Distance the front must travel to clear the element, CSS px. */
  distance: number;
  /** Width of the bending band at full size, CSS px. */
  band: number;
}

/** The wave at progress `u`: pull, launch, crossing, glow left on the rim. */
export function frameAt(
  { u, time, distance, band }: TimelineInput,
  into: WaveFrame,
): WaveFrame {
  const v = clamp01((u - LAUNCH) / (1 - LAUNCH - 0.1));
  into.pull = smooth(0, 0.07, u) * (1 - smooth(0.09, 0.17, u));
  into.reach = distance * (1 - (1 - v) ** 1.3) - band * 0.5 * (1 - v);
  into.band = band * (0.4 + 0.6 * smooth(0, 0.3, v));
  into.glow = smooth(0, 0.05, v) * (1 - smooth(0.72, 1, v));
  into.rim = smooth(0.12, 0.42, v) * (1 - smooth(0.6, 1, u));
  into.settle = smooth(0.1, 0.8, v);
  into.time = time;
  return into;
}
